import java.io.*;import java.nio.file.*;import java.util.*;
class Height1024Test{
 static Object read(int t,DataInputStream d)throws Exception{return switch(t){case 1->d.readByte();case 2->d.readShort();case 3->d.readInt();case 4->d.readLong();case 5->d.readFloat();case 6->d.readDouble();case 7->{byte[] a=new byte[d.readInt()];d.readFully(a);yield a;}case 8->d.readUTF();case 9->{int kind=d.readUnsignedByte(),n=d.readInt();var list=new ArrayList<Object>();for(int i=0;i<n;i++)list.add(read(kind,d));yield list;}case 10->{var map=new HashMap<String,Object>();for(int kind;(kind=d.readUnsignedByte())!=0;)map.put(d.readUTF(),read(kind,d));yield map;}case 11->{int[]a=new int[d.readInt()];for(int i=0;i<a.length;i++)a[i]=d.readInt();yield a;}case 12->{long[]a=new long[d.readInt()];for(int i=0;i<a.length;i++)a[i]=d.readLong();yield a;}default->throw new IOException("NBT type "+t);};}
 public static void main(String[]args)throws Exception{var w=new TerraForge.World(32,62,71);Arrays.fill(w.height,1000);w.height[0]=1024;w.environment.water=EnvironmentMap.filled(1024,62);w.environment.water[1]=800;w.height[1]=799;w.environment.snow=EnvironmentMap.filled(1024,.5f);ExtendedHeight.configure(w);if(w.h(0,0)!=1024||w.buildHeight!=1152||ExtendedHeight.heightmapBits(w.buildHeight)!=11)throw new AssertionError("1024 height clipped");Path project=Files.createTempFile("height1024-",".terra");TerraForge.writeProject(w,project);var loaded=TerraForge.readProject(project);Files.delete(project);if(loaded.h(0,0)!=1024||loaded.environment.water[1]!=800||loaded.buildHeight!=1152)throw new AssertionError("Tall map save/read failed");byte[] bytes=TerraForge.chunk(w,0,0);var in=new DataInputStream(new ByteArrayInputStream(bytes));in.readByte();in.readUTF();var nbt=(Map<?,?>)read(10,in);var sections=(List<?>)nbt.get("sections");if(sections.size()!=72||sections.stream().noneMatch(o->((Number)((Map<?,?>)o).get("Y")).intValue()==64))throw new AssertionError("Missing high chunk section");var hm=(Map<?,?>)nbt.get("Heightmaps");long[] values=(long[])hm.get("WORLD_SURFACE");if(values.length!=52||(values[0]&2047)!=1090)throw new AssertionError("High heightmap truncated");Path dest=Path.of(args[0]);TerraForge.writeWorld(w,dest);String type=Files.readString(dest.resolve("datapacks/terraforge_height/data/terraforge/dimension_type/overworld1024.json"));if(!type.contains("\"height\":1152")||!type.contains("\"min_y\":-64"))throw new AssertionError("Invalid dimension height");System.out.println("PASS: Y1024 save/read, elevated water, 72 sections, 11-bit heightmap and extended-height world export");}
}
